package me.neobliz1.ecomonitoring.platform.history.infrastructure.adapter.outbound.persistence.postgres.jpa;import me.neobliz1.ecomonitoring.platform.history.domain.model.entity.WeatherMapBucket;import org.jspecify.annotations.NonNull;import org.springframework.data.jpa.repository.EntityGraph;import org.springframework.data.jpa.repository.JpaRepository;import org.springframework.stereotype.Repository;import java.util.Optional;import java.util.UUID;@Repositorypublic interface HistoricalWeatherMapJpaRepository extends JpaRepository<WeatherMapBucket, UUID> {    @NonNull    @Override    @EntityGraph(attributePaths = { WeatherMapBucket.Fields.gridCells })    Optional<WeatherMapBucket> findById(UUID id);    Optional<WeatherMapBucket> findByTimestampBucketAndIntervalMinutes(Long timestampBucket, Integer intervalMinutes);    Optional<WeatherMapBucket> findFirstByTimestampBucketLessThanAndIntervalMinutesOrderByTimestampBucketDesc(            Long timestampBucket, Integer intervalMinutes);}